public void selectExample()
{
    AIBBookTable bookTable;
    AIBAuthorTable authorTable;

    while select FirstName, LastName from authorTable
        join Id, Name from bookTable
        where authorTable.RecId == bookTable.Author
        && bookTable.Genre == AIBGenreEnum::Fantasy
    {
        Info(strFmt('%1 %2 - %3 %4', bookTable.Id, bookTable.Name, authorTable.FirstName, authorTable.LastName));
    }
}

public void reuseExistingQuery()
{
    Query aibBookAuthorFantasyQuery = new Query(queryStr(aibBookAuthorFantasyQuery));

    this.runQuery(aibBookAuthorFantasyQuery);
}

public void buildQueryFromCode()
{
    Query aibBookAuthorFantasyQuery = new Query();

    QueryBuildDataSource qbdsAuthorTable = aibBookAuthorFantasyQuery.addDataSource(tableNum(AIBAuthorTable));
    QueryBuildDataSource qbdsBookTable = qbdsAuthorTable.addDataSource(tableNum(AIBBookTable));

    qbdsBookTable.joinMode(JoinMode::InnerJoin);

    qbdsBookTable.addLink(fieldNum(AIBAuthorTable, RecId), fieldNum(AIBBookTable, Author), qbdsAuthorTable.name());

    QueryBuildRange qbrGenre = qbdsBookTable.addRange(fieldNum(AIBBookTable, Genre));
    qbrGenre.value(queryValue(AIBGenreEnum::Fantasy));

    this.runQuery(aibBookAuthorFantasyQuery);
}

public void runQuery(Query _q)
{
    QueryRun qr = new QueryRun(_q);

    while(qr.next())
    {
        AIBBookTable bookTable = qr.get(tableNum(AIBBookTable));
        AIBAuthorTable authorTable = qr.get(tableNum(AIBAuthorTable));

        Info(strFmt('%1 %2 - %3 %4', bookTable.Id, bookTable.Name, authorTable.FirstName, authorTable.LastName));
    }
}
